import { after } from 'next/server';

async function logPageView(page: string) {
  // Simulates an analytics service call (e.g. a database write or HTTP request)
  await fetch('https://analytics.example.com/collect', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ page, timestamp: new Date().toISOString() }),
  });
}

export default function Home() {
  // Schedules the analytics call to run after the response is sent.
  // The user never waits for this work.
  after(async () => {
    await logPageView('/');
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Your page view has been recorded.</p>
    </main>
  );
}

